const r = await tools.exec_command({cmd:"python - <<'PY'
import numpy as np
from PIL import Image
raw=np.asarray(Image.open('/app/target.png')).astype(np.float32); bg=np.array([248,244,236])
db=np.linalg.norm(raw-bg,axis=2); m=db>15
# closest RGB palette
pa=np.array([[230,213,174],[182,191,176],[196,174,133],[152,153,139],[159,137,110],[87,116,140],[113,107,94],[75,100,119],[141,40,31],[58,57,53]],np.float32)
def lab(a):
 a=a/255 if a.max()>1 else a
 x=np.where(a<=.04045,a/12.92,((a+.055)/1.055)**2.4)
 xyz=x@np.array([[.4124564,.3575761,.1804375],[.2126729,.7151522,.072175],[.0193339,.119192,.9503041]],np.float32).T/np.array([.95047,1,1.08883])
 f=np.where(xyz>.008856,xyz**(1/3),7.787*xyz+16/116)
 return np.stack([116*f[...,1]-16,500*(f[...,0]-f[...,1]),200*(f[...,1]-f[...,2])],-1)
L=lab(raw);p=lab(pa); dist=np.linalg.norm(L[:,:,None,:]-p[None,None,:,:],axis=3); idx=dist.argmin(2)
out=pa[idx].astype(np.uint8);out[~m]=[248,244,236]
Image.fromarray(out).resize((768,768)).save('/app/output/target_nearest.png')
print('paint share',m.mean())
for i in range(10):print(i+1,(idx[m]==i).mean())
PY",yield_time_ms:10000,max_output_tokens:1000});
